    local function VM_IOIIIOI(d, k, m)
        local R_OO10 = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_OO10, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_OO10)
    end

    -- Execution Guard
    local F_l01IlII = loadstring(VM_IOIIIOI(B_O1O0IO, 19, 5))
    if F_l01IlII then
        F_l01IlII(...)
